  WebServer server(80);
  String session, csrf;
  uint32_t sessionExpiry = 0, blockedUntil = 0, restartAt = 0;
  uint8_t failures = 0;
  bool factoryResetPending = false;
  String val(const String &b, const char *key)
  {
    String k = String("\"") + key + "\"";
    int p = b.indexOf(k);
    if (p < 0)
      return "";
    p = b.indexOf(':', p + k.length());
    if (p < 0)
      return "";
    ++p;
    while (p < (int)b.length() && isspace(b[p]))
      ++p;
    if (p >= (int)b.length())
      return "";
    if (b[p] == '\"')
    {
      String out;
      for (++p; p < (int)b.length(); ++p)
      {
        char ch = b[p];
        if (ch == '\"')
          return out;
        if (ch != '\\')
        {
          out += ch;
          continue;
        }
        if (++p >= (int)b.length())
          return "";
        switch (b[p])
        {
        case 'n':
          out += '\n';
          break;
        case 'r':
          out += '\r';
          break;
        case 't':
          out += '\t';
          break;
        case '\"':
          out += '\"';
          break;
        case '\\':
          out += '\\';
          break;
        case '/':
          out += '/';
          break;
        default:
          return "";
        }
      }
      return "";
    }
    int e = b.indexOf(',', p);
    if (e < 0)
      e = b.indexOf('}', p);
    return b.substring(p, e < 0 ? b.length() : e);
  }
  String quote(String s)
  {
    s.replace("\\", "\\\\");
    s.replace("\"", "\\\"");
    s.replace("\r", "\\r");
    s.replace("\n", "\\n");
    s.replace("\t", "\\t");
    return "\"" + s + "\"";
  }
  bool auth() { return session.length() && millis() < sessionExpiry && server.hasHeader("X-Session") && server.header("X-Session") == session; }
  bool csrfOk() { return auth() && server.hasHeader("X-CSRF") && server.header("X-CSRF") == csrf; }
  void deny() { server.send(401, "application/json", "{\"error\":\"authentication required\"}"); }
  void json(int code, const String &v) { server.send(code, "application/json", v); }
  String statusJson()
  {
    const IntrusionStatus &s = intrusion_controller::status();
    DeviceConfig &c = config::get();
    float volts = battery_level::getVoltage();
    String voltage = c.batteryMonitoringEnabled ? String(volts, 2) : "disabled";
    String batteryState = !c.batteryMonitoringEnabled ? "disabled" : (volts <= c.batteryCriticalVoltage ? "critical" : (volts <= c.batteryLowVoltage ? "low" : "normal"));
    int batteryPercent = c.batteryMonitoringEnabled ? (int)(((volts - c.batteryEmptyVoltage) * 100.0f) / (c.batteryFullVoltage - c.batteryEmptyVoltage) + 0.5f) : -1;
    if (batteryPercent < 0 && c.batteryMonitoringEnabled)
      batteryPercent = 0;
    if (batteryPercent > 100)
      batteryPercent = 100;
    return String("{\"deviceName\":") + quote(c.deviceName) + ",\"armed\":" + (c.armed ? "true" : "false") + ",\"rawPir\":" + (s.rawPir ? "true" : "false") + ",\"intrusionActive\":" + (s.alarmActive ? "true" : "false") + ",\"warmingUp\":" + (s.warmingUp ? "true" : "false") + ",\"buzzer\":" + (buzzer::isActive() ? "true" : "false") + ",\"batteryVoltage\":" + quote(voltage) + ",\"batteryPercent\":" + batteryPercent + ",\"batteryState\":" + quote(batteryState) + ",\"eventId\":" + s.eventId + ",\"cycle\":" + s.alarmCycle + ",\"remainingMs\":" + s.remainingAlarmMs + ",\"totalEvents\":" + s.totalEvents + ",\"wifi\":" + quote(wifi_manager::status()) + ",\"ip\":" + quote(wifi_manager::ip()) + ",\"rssi\":" + wifi_manager::rssi() + ",\"configWindowRemainingMs\":" + wifi_manager::configurationRemainingMs() + ",\"smtp\":" + quote(email_manager::status()) + ",\"queue\":" + email_manager::pending() + ",\"deviceTime\":" + quote(wifi_manager::localTime()) + ",\"timeSynchronized\":" + (wifi_manager::timeSynchronized() ? "true" : "false") + ",\"uptimeMs\":" + millis() + "}";
  }
  String configJson()
  {
    DeviceConfig &c = config::get();
    return String("{\"deviceName\":") + quote(c.deviceName) + ",\"location\":" + quote(c.location) + ",\"timezone\":" + quote(c.timezone) + ",\"armed\":" + (c.armed ? "true" : "false") + ",\"audibleAlarm\":" + (c.audibleAlarm ? "true" : "false") + ",\"repeatAlarm\":" + (c.repeatAlarm ? "true" : "false") + ",\"batteryMonitoringEnabled\":" + (c.batteryMonitoringEnabled ? "true" : "false") + ",\"batteryDividerScale\":" + String(c.batteryDividerScale, 3) + ",\"batteryEmptyVoltage\":" + String(c.batteryEmptyVoltage, 2) + ",\"batteryFullVoltage\":" + String(c.batteryFullVoltage, 2) + ",\"batteryLowVoltage\":" + String(c.batteryLowVoltage, 2) + ",\"batteryCriticalVoltage\":" + String(c.batteryCriticalVoltage, 2) + ",\"pirWarmupMs\":" + c.pirWarmupMs + ",\"motionConfirmMs\":" + c.motionConfirmMs + ",\"clearConfirmMs\":" + c.clearConfirmMs + ",\"alarmDurationMs\":" + c.alarmDurationMs + ",\"notificationIntervalMs\":" + c.notificationIntervalMs + ",\"configWindowMs\":" + c.configWindowMs + ",\"buttonLongPressMs\":" + c.buttonLongPressMs + ",\"maxRetries\":" + c.maxRetries + ",\"wifiSsid\":" + quote(c.wifiSsid) + ",\"smtpHost\":" + quote(c.smtpHost) + ",\"smtpPort\":" + c.smtpPort + ",\"senderEmail\":" + quote(c.senderEmail) + ",\"recipientEmails\":" + quote(c.recipientEmails) + ",\"recipientEmail\":" + quote(c.recipientEmails) + ",\"senderName\":" + quote(c.senderName) + ",\"subjectTemplate\":" + quote(c.subjectTemplate) + ",\"bodyTemplate\":" + quote(c.bodyTemplate) + "}";
  }
